import java.util.*;

class PrefixTree {
    private static class Node {
        Node[] next = new Node[26]; // one link per lowercase letter
        boolean isEnd;              // true if a word finishes here
    }

    private final Node root = new Node();

    public PrefixTree() {
    }

    public void insert(String word) {
        Node cur = root;
        for (char c : word.toCharArray()) {
            int k = c - 'a';
            if (cur.next[k] == null) cur.next[k] = new Node();
            cur = cur.next[k];
        }
        cur.isEnd = true;
    }

    public boolean search(String word) {
        Node node = walk(word);
        return node != null && node.isEnd; // path must exist AND a word must end here
    }

    public boolean startsWith(String prefix) {
        return walk(prefix) != null; // the path existing is enough
    }

    // follow the letters of s; null if the path breaks
    private Node walk(String s) {
        Node cur = root;
        for (char c : s.toCharArray()) {
            cur = cur.next[c - 'a'];
            if (cur == null) return null;
        }
        return cur;
    }
}

