class PrefixTree {
  constructor() { this.words = new Set(); this.pre = new Set(); }
  insert(w) { this.words.add(w); for (let i = 1; i <= w.length; i++) this.pre.add(w.slice(0, i)); }
  search(w) { return this.words.has(w); }
  startsWith(p) { return this.pre.has(p); }
}
